<script lang="ts" setup>
/* eslint-disable */
import { ref, watch, onMounted, computed } from 'vue'
import { ArrowRightBold } from '@element-plus/icons-vue'
import { connectMetaMask, connectTon, uploadToFile, getOS, sleep } from '@/utils/index.ts'
import { callApp } from '@/utils/bridge.ts'
import { setTaskStatus,getActStepStatus } from '@/utils/taskManager'
import shareView from './shareView.vue'
import { useUserStore } from '@/store/userStore'
import { TonConnect } from '@tonconnect/sdk';
import axiosInstance from '@/utils/axios.ts'
import { defineComponent } from 'vue';
import { useRoute, useRouter } from 'vue-router'
import html2canvas from 'html2canvas'
const tonConnect = new TonConnect();
const userStore = useUserStore();
const route = useRoute()
const router = useRouter()
const shareId = ref(0)
import QRCode from 'qrcode'
const captureArea = ref(null)
const props = defineProps({
  steps: Array,
  project: Object,
  isAve: Boolean
})
onMounted(() => {
})
const emit = defineEmits(['sendMessage']);

// 触发事件并传递参数
const sendDataToParent = ($type) => {
  if($type < 0) {
    emit('sendMessage', { status: -1 });
  }
};
const open = ($url) => {
  window.open($url)
}
const activeNames = ref([0,1])
const step = async ($item)=>{
  if(!props.isAve) {
    sendDataToParent(-1)
  }
  if($item.title.indexOf('链接钱包') > -1 || $item.title.indexOf('Connect') > -1) {
    await connect()
  }
  if($item.title.indexOf('分享') > -1 || $item.title.indexOf('Share') > -1 ) {
    share($item)
    //shareOnTwitter()
  }
}
const connect = async ()=>{
  await connectMetaMask(userStore)
  try {
        const data = {
          user_address: userStore.$state.address,
          invite_code: "y1HuMg",
          project_id: 1
        }
        const dataV = {
          user_address: userStore.$state.address,
          project_id: 1
        }
        const dataTask  = {
          user_address: userStore.$state.address,
          project_id: route.query.activity_id,
          steps_status: [1,2]
        }
        const doRes = await axiosInstance.post('/user/dotask',dataTask);
        const codeRes = await axiosInstance.get('/user/task/'+ route.query.activity_id + '/' + userStore.$state.address);
        const response = await axiosInstance.post('/user/jointask',data);
        //const codeRes = await axiosInstance.get('/user/getcode/' + userStore.$state.address);
        // if(codeRes.data && codeRes.data.status === 1) {
        //   console.log('codeRes',codeRes)
        //   setQR(codeRes.data.data)
        //   userStore.setCode(codeRes.data.data)
        // }
        console.log('userStore',userStore)
        console.log(response.data);
        console.log('doRes',doRes.data);
        await sleep(1000)
        props.steps[0].status = 1
        setTaskStatus(route.query.activity_id,1,1,2)
      } catch (error) {
        console.error('Request failed:', error);
  }
}

const setQR = ($code) =>{
  const qrData = "https://conquerorzzz.github.io/mktapp/?lang=zh"
  QRCode.toCanvas(document.getElementById('qrcode'), $code, {
    width: 200,
    color: {
      dark: '#000000',  // 二维码颜色
      light: '#FFFFFF'  // 背景颜色
    }
    }, function (error) {
      if (error) console.error(error);
  })
  const canvas = document.getElementById('qrcode')
  canvas.toBlob(blob => {
    if (blob) {
        // 3. 将 Blob 转换为 File 对象
        const file = new File([blob], "qrcode.png", { type: "image/png" });
        uploadToFile(file)
    } else {
        console.log('failed to blob')
    }
  }, "image/png");
}
const shareFlag = ref(false)
const share = ($item) => {
  shareId.value = $item.id
  shareFlag.value = true
  //setQR(userStore.$state.code)
}
const shareOnTwitter = async () => {
  let os = getOS()
  console.log('os:',os>0 ? 'ios' : 'Android')
  const content = 'test text test text test text test text test text test text test text test text'
  const image_url = 'https://m.ave.ai/icon-default.png'
  const base64img = await convertToImage()
  if(os < 1){
    if (window._tw_ && typeof window._tw_.gotoPostTwitter === 'function') {
      const res =  window._tw_.gotoPostTwitter(content,image_url,base64img)
      console.log('share to twitter' ,res)
    } else {
      alert('The method gotoPostTwitter does not exist or the dependency is not injected')
    }
  }
  if(os > 0) {
    const data = {
      content: 'test text test text test text test text test text test text test text test text',
      image_url: 'https://m.ave.ai/icon-default.png',
    }
    const res1 =  await callApp('gotoPostTwitter',data)
    console.log('share to twitter1' ,res1)
  }
  await sleep(3000)
  props.steps[1].status = 1
  setTaskStatus(route.query.activity_id,2,1,2)
}
const convertToImage = async () => {
  if (!captureArea.value) return

  try {
    // 使用 html2canvas 将 DOM 元素转换为 Canvas
    const canvas = await html2canvas(captureArea.value)
    
    // 转换为 Base64 格式的图片
    const base64Image = canvas.toDataURL("image/png")
    console.log("Base64 Image:", base64Image)
    return base64Image
  } catch (error) {
    console.error("Error converting to image:", error)
  }
}
const handleUpdateStatus = async ($data) => {
  console.log('share',$data)
  await sleep(3000)
  props.steps[1].status = 1
  props.steps.forEach((e,index) => {
    if(e.id === $data.id) {
      props.steps[index] = 1
    }
  });
  setTaskStatus(route.query.activity_id,$data.id,1,2)

}
</script>

